def BFS():
    while queue:
        q = queue.popleft()
        z, x, y = q[0]
        for i in range(6):
            dx = x + nx[i]
            dy = y + ny[i]
            dz = z + nz[i]
            if dx < 0 or dx >= N or dy < 0 or dy >= M or dz < 0 or dz >= H:
                continue
            if arr[dz][dx][dy] == 0:
                arr[dz][dx][dy] = 1
                queue.append(((dz,dx,dy), q[1]+1))

    if checkMap():
        return q[1]
    return -1

